75	
76	export async function editProduct(
77	  businessId: string,
78	  productId: string,
79	  _prevState: EditProductState,
80	  formData: FormData,
81	): Promise<EditProductState> {
82	  const name = (formData.get("name") as string)?.trim();
83	  const category = (formData.get("category") as string)?.trim();
84	  const priceRaw = formData.get("price") as string;
85	  const costRaw = formData.get("cost") as string;
86	  const minStockRaw = formData.get("minStock") as string;
87	  const emoji = (formData.get("emoji") as string)?.trim();
88	
89	  if (!name) {
90	    return { error: "Nama produk wajib diisi." };
91	  }
92	
93	  const price = Number(priceRaw);
94	  if (!priceRaw || Number.isNaN(price) || price < 0) {
95	    return { error: "Harga jual harus angka dan tidak boleh negatif." };
96	  }
97	
98	  const cost = costRaw ? Number(costRaw) : 0;
99	  if (Number.isNaN(cost) || cost < 0) {
100	    return { error: "Modal (HPP) harus angka dan tidak boleh negatif." };
101	  }
102	
103	  const minStock = minStockRaw ? Number(minStockRaw) : 0;
104	  if (Number.isNaN(minStock) || minStock < 0) {
105	    return { error: "Stok minimum harus angka dan tidak boleh negatif." };
106	  }
107	
108	  const supabase = await createClient();
109	  const { error } = await supabase
110	    .from("products")
111	    .update({
112	      name,
113	      category: category || null,
114	      price,
115	      cost,
116	      min_stock: minStock,
117	      emoji: emoji || null,
118	    })
119	    .eq("id", productId)
120	    .eq("business_id", businessId);
121	
122	  if (error) {
123	    return { error: error.message };
124	  }
125	
126	  await logActivity(supabase, businessId, "produk", "info", `Produk diubah: ${name}`);
127	  revalidatePath(`/business/${businessId}/products`);
128	  return { error: null };
129	}
130	
131	export type AdjustStockResult = { error: string | null };
132	
133	export async function adjustProductStock(
134	  businessId: string,
135	  productId: string,
136	  newStock: number,
137	  reason: string,
138	): Promise<AdjustStockResult> {
139	  if (Number.isNaN(newStock) || newStock < 0) {
140	    return { error: "Stok fisik harus angka dan tidak boleh negatif." };
141	  }
142	  reason = reason.trim();
143	  if (!reason) {
144	    return { error: "Alasan penyesuaian wajib diisi." };
145	  }
146	
147	  const supabase = await createClient();
148	
149	  const { data: product } = await supabase
150	    .from("products")
151	    .select("id, name, stock")
152	    .eq("id", productId)
153	    .eq("business_id", businessId)
154	    .single();
155	
156	  if (!product) {
157	    return { error: "Produk tidak ditemukan." };
158	  }
159	
160	  const stockBefore = Number(product.stock);
161	  const diff = newStock - stockBefore;
162	
163	  if (diff === 0) {
164	    return { error: "Stok fisik sama dengan stok sistem, tidak ada yang disesuaikan." };
165	  }
166	
167	  const { error: updateError } = await supabase
168	    .from("products")
169	    .update({ stock: newStock })
170	    .eq("id", productId);
171	
172	  if (updateError) {
173	    return { error: updateError.message };
174	  }
175	
176	  await supabase.from("stock_adjustments").insert({
177	    business_id: businessId,
178	    product_id: productId,
179	    item_name: product.name,
180	    stock_before: stockBefore,
181	    stock_after: newStock,
182	    diff,
183	    reason,
184	  });
185	
186	  await logActivity(
187	    supabase,
188	    businessId,
189	    "produk",
190	    "warning",
191	    `Penyesuaian stok: ${product.name}`,
192	    `${stockBefore} → ${newStock} (${diff > 0 ? "+" : ""}${diff}) · ${reason}`,
193	  );
194	  revalidatePath(`/business/${businessId}/products`);
195	  return { error: null };
196	}
197	
198	export async function deleteProduct(businessId: string, productId: string) {
199	  const supabase = await createClient();
200	
201	  const { data: product } = await supabase
202	    .from("products")
203	    .select("name")
204	    .eq("id", productId)
205	    .eq("business_id", businessId)
206	    .maybeSingle();
207	
208	  await supabase
209	    .from("products")
210	    .update({ deleted_at: new Date().toISOString() })
211	    .eq("id", productId)
212	    .eq("business_id", businessId);
213	
214	  if (product) {
215	    await logActivity(supabase, businessId, "produk", "warning", `Produk dihapus: ${product.name}`);
216	  }
217	  revalidatePath(`/business/${businessId}/products`);
218	}
