      price,
      cost,
      min_stock: minStock,
      emoji: emoji || null,
      barcode: barcode || null,
    })
    .eq("id", productId)
    .eq("business_id", businessId);

  if (error) {
    if (error.code === "23505") {
      return { error: "Barcode ini sudah dipakai produk lain." };
    }
    return { error: error.message };
  }

