1	-- Ticket sales never posted to the journal at all (deliberate original
2	-- design since tickets have no HPP/COGS concept — see the top-of-file
3	-- comment in 20260706200000_ticket_venue.sql). That meant tiket businesses
4	-- had zero financial visibility in Akuntansi/Laporan/Neraca. This adds
5	-- revenue-only journal posting (no HPP/Persediaan lines — there's nothing
6	-- to debit, tickets have no cost-basis columns anywhere in the schema),
7	-- mirroring checkout_transaction/void_transaction's exact PPN-split
8	-- pattern (see 20260710140000_ppn_liability.sql): debit Kas & Bank for the
9	-- full total, credit revenue for subtotal+service only, credit PPN
10	-- Keluaran (2-200) for tax since that's collected on the tax office's
11	-- behalf, not earned revenue.
12	
13	-- New revenue account so ticket income is visible separately from product
14	-- sales (4-001) in Laba Rugi/Neraca, instead of blending into one bucket.
15	-- Relies on the (business_id, code) unique constraint seed_default_accounts
16	-- already depends on for its "on conflict do nothing" upsert.
17	create or replace function private.seed_default_accounts(p_business_id uuid)
18	returns void
19	language plpgsql
20	security definer
21	set search_path = ''
22	as $$
23	begin
