27	    (p_business_id, '1-100', 'Piutang Usaha', 'aset', 'debit', true),
28	    (p_business_id, '1-200', 'Persediaan', 'aset', 'debit', true),
29	    (p_business_id, '1-500', 'Peralatan', 'aset', 'debit', true),
30	    (p_business_id, '1-501', 'Akumulasi Penyusutan', 'aset', 'debit', true),
31	    (p_business_id, '2-001', 'Utang Dagang', 'kewajiban', 'kredit', true),
32	    (p_business_id, '2-100', 'Utang Gaji', 'kewajiban', 'kredit', true),
33	    (p_business_id, '2-200', 'PPN Keluaran (Utang Pajak)', 'kewajiban', 'kredit', true),
