36	    (p_business_id, '4-001', 'Pendapatan Penjualan', 'pendapatan', 'kredit', true),
37	    (p_business_id, '4-002', 'Pendapatan Tiket', 'pendapatan', 'kredit', true),
38	    (p_business_id, '5-001', 'Beban Pokok Penjualan (HPP)', 'beban', 'debit', true),
39	    (p_business_id, '5-100', 'Beban Gaji', 'beban', 'debit', true),
40	    (p_business_id, '5-101', 'Beban Listrik & Air', 'beban', 'debit', true),
41	    (p_business_id, '5-102', 'Beban Sewa', 'beban', 'debit', true),
42	    (p_business_id, '5-103', 'Beban Marketing', 'beban', 'debit', true),
43	    (p_business_id, '5-104', 'Beban Perlengkapan', 'beban', 'debit', true),
44	    (p_business_id, '5-105', 'Beban Penyusutan', 'beban', 'debit', true),
