    const { categoryId, index } = lastAddedRef.current;
    lastAddedRef.current = null;
    unitInputRefs.current.get(`${categoryId}-${index}`)?.focus();
  }, [unitsByCategory]);

  function removeUnit(categoryId: string, index: number) {
    setUnitsByCategory((prev) => {
