97	export type TicketCategoryState = { error: string | null };
98	
99	type ParsedTicketCategoryFields =
100	  | { error: string }
101	  | {
102	      error: null;
103	      name: string;
104	      priceWeekday: number;
105	      priceHoliday: number;
106	      memberPrice: number;
107	    };
108	
109	function parseTicketCategoryFields(formData: FormData): ParsedTicketCategoryFields {
110	  const name = (formData.get("name") as string)?.trim();
111	  const priceWeekday = Number(formData.get("priceWeekday"));
112	  const priceHoliday = Number(formData.get("priceHoliday"));
113	  const memberPrice = Number(formData.get("memberPrice"));
114	
115	  if (!name) return { error: "Nama kategori wajib diisi." };
116	  if (Number.isNaN(priceWeekday) || priceWeekday < 0) {
117	    return { error: "Harga hari kerja harus angka dan tidak boleh negatif." };
118	  }
119	  if (Number.isNaN(priceHoliday) || priceHoliday < 0) {
120	    return { error: "Harga hari libur harus angka dan tidak boleh negatif." };
121	  }
122	  if (Number.isNaN(memberPrice) || memberPrice < 0) {
123	    return { error: "Harga member harus angka dan tidak boleh negatif." };
124	  }
125	
126	  return { error: null, name, priceWeekday, priceHoliday, memberPrice };
127	}
128	
129	export async function addTicketCategory(
130	  businessId: string,
131	  _prevState: TicketCategoryState,
132	  formData: FormData,
133	): Promise<TicketCategoryState> {
134	  const parsed = parseTicketCategoryFields(formData);
135	  if (parsed.error !== null) return { error: parsed.error };
